import { Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, Vector2 } from 'three/webgpu';
import { uv, mix, smoothstep, vec3, color, FloatNode, include } from 'three/tsl';
import gsap from 'gsap';
import { orbit } from '@/primitives';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } = ctx.THREE;
  const root = new Group();

  // ---------- Backdrop Gradient ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const gradStops = config.visualSpec?.colors?.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const c0 = color(gradStops[0].hex);
  const c1 = color(gradStops[1].hex);
  const c2 = color(gradStops[2].hex);
  const uvNode = uv();
  const t = uvNode.y;
  const firstMix = mix(c0, c1, smoothstep(0, gradStops[1].at, t));
  const finalColor = mix(firstMix, c2, smoothstep(gradStops[1].at, 1, t));

  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = finalColor;
  backdropMat.roughness = 0.8;
  backdropMat.metalness = 0.0;

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);

  // ---------- Contact Shadow ----------
  const shadowGeom = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshStandardNodeMaterial();
  shadowMat.colorNode = color('#000000');
  shadowMat.transparent = true;
  shadowMat.opacity = 0.5;
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.2, 0);
  root.add(shadow);

  // ---------- Jewel Pivot ----------
  const jewelGeom = new SphereGeometry(0.12, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial();
  jewelMat.colorNode = color('#ff2a38');
  jewelMat.transmission = 0.6;
  jewelMat.ior = 1.76;
  jewelMat.emissiveNode = color('#ff2a38');
  jewelMat.emissiveIntensity = 1.8;
  const jewel = new Mesh(jewelGeom, jewelMat);
  jewel.position.set(0, 0, 0);
  root.add(jewel);

  // ---------- Arbor Shafts ----------
  const shaftGeom = new CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshStandardNodeMaterial();
  shaftMat.colorNode = color('#16161d');
  shaftMat.roughness = 0.6;
  shaftMat.metalness = 0.0;

  const shaft1 = new Mesh(shaftGeom, shaftMat);
  shaft1.rotation.x = Math.PI / 2;
  shaft1.position.set(0, 0, 0);
  root.add(shaft1);

  const shaft2 = shaft1.clone();
  shaft2.position.set(1.15, 0.35, -0.1);
  root.add(shaft2);

  // ---------- Text ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize ?? (item.role === 'headline' ? 68 : 18),
      color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    txtObj.position.y = item.role === 'headline' ? -1.7 : -2.1;
    root.add(txtObj);
  }

  // ---------- Load GLB ----------
  const glbUrl = config.meshUrl;
  let primaryGear = null;
  let secondaryGear = null;
  const timelines = [];

  ctx.glbLoader.loadGLB(glbUrl).then((gltf) => {
    const gltfScene = gltf.scene || gltf;
    root.add(gltfScene);

    // Assume the first mesh is the primary gear
    primaryGear = gltfScene.getObjectByProperty('type', 'Mesh');
    if (primaryGear) {
      // Scale primary gear to 1.6 unit diameter if needed
      const desiredDiameter = 1.6;
      const bbox = new ctx.THREE.Box3().setFromObject(primaryGear);
      const currentDiameter = Math.max(bbox.max.x - bbox.min.x, bbox.max.y - bbox.min.y);
      const scaleFactor = desiredDiameter / currentDiameter;
      primaryGear.scale.setScalar(scaleFactor);
      primaryGear.position.set(0, 0, 0);
    }

    // Clone secondary gear
    if (primaryGear) {
      secondaryGear = primaryGear.clone();
      const secondaryScale = (0.9 / 1.6) * primaryGear.scale.x; // target 0.9 unit diameter
      secondaryGear.scale.setScalar(secondaryScale);
      secondaryGear.position.set(1.15, 0.35, -0.1);
      root.add(secondaryGear);
    }

    // ---------- Gear Rotation ----------
    if (primaryGear) {
      const primarySpeed = 0.08; // rad/s
      const primaryTl = gsap.to(primaryGear.rotation, {
        y: '+=6.283185307179586',
        duration: (2 * Math.PI) / primarySpeed,
        repeat: -1,
        ease: 'none',
      });
      timelines.push(primaryTl);
    }

    if (secondaryGear) {
      const secondarySpeed = -0.142; // rad/s (reverse)
      const secondaryTl = gsap.to(secondaryGear.rotation, {
        y: '+=6.283185307179586',
        duration: (2 * Math.PI) / Math.abs(secondarySpeed),
        repeat: -1,
        ease: 'none',
      });
      timelines.push(secondaryTl);
    }
  });

  // ---------- Cinematic Primitive ----------
  const orbitPrim = orbit(root, { speed: 0.08, radius: 0.2 });
  const primitiveRefs = [orbitPrim];

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometries & materials we created
    backdropGeom.dispose();
    backdropMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    jewelGeom.dispose();
    jewelMat.dispose();
    shaftGeom.dispose();
    shaftMat.dispose();
    if (primaryGear && primaryGear.geometry) primaryGear.geometry.dispose();
    if (primaryGear && primaryGear.material) primaryGear.material.dispose();
    if (secondaryGear && secondaryGear.geometry) secondaryGear.geometry.dispose();
    if (secondaryGear && secondaryGear.material) secondaryGear.material.dispose();

    // Kill GSAP timelines
    timelines.forEach((t) => t.kill());

    // Primitive cleanups
    primitiveRefs.forEach((p) => p && p.cleanup && p.cleanup());
  };

  // Handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  return root;
}
